602				totalNew += n
603				totalDup += d
604				if err != nil {
605					errs = append(errs, err)
606				}
607				mu.Unlock()
608			}()
609		}
610		wg.Wait()
611		if len(errs) != 0 {
612			t.Fatalf("unexpected errors: %v", errs)
613		}
614		if totalNew != 1 || totalDup != 19 {
