380	// corruptNodeFile overwrites one node's saved file with raw content.
381	func corruptNodeFile(t *testing.T, dir, node, content string) {
382		t.Helper()
383		if err := os.WriteFile(nodeFileHexPath(dir, node), []byte(content), 0o644); err != nil {
384			t.Fatal(err)
385		}
386	}
387	
388	// readNodeFile returns the current raw bytes of a node's file.
389	func readNodeFile(t *testing.T, dir, node string) string {
390		t.Helper()
391		b, err := os.ReadFile(nodeFileHexPath(dir, node))
392		if err != nil {
393			t.Fatal(err)
394		}
395		return string(b)
396	}
397	
398	// strictChecksum replicates the store's checksum over the canonical JSON of a
399	// single record slice, so a test can forge a checksum matching a tampered
400	// interpretation. canonicalJSON must be the store's marshaled record form.
401	func strictChecksum(canonicalJSON string) string {
402		sum := sha256.Sum256([]byte(canonicalJSON))
403		return hex.EncodeToString(sum[:])
404	}
405	
406	// envelope wraps a raw records array in a well-formed store file.
407	func envelope(checksum, recordsJSON string) string {
408		return `{"format":"edgefleet-heartbeats-v1","checksum":"` + checksum + `","records":` + recordsJSON + `}`
409	}
410	
411	// TestCLIStoredCorruptionRefusedByQueries exercises the user-visible contract:
412	// a saved record with a missing, null or duplicated telemetry field corrupts
413	// the node's data even when the checksum matches the interpreted values; every
414	// query for that node fails on stderr with a non-zero exit and prints nothing
415	// on stdout, while other nodes keep working.
416	func TestCLIStoredCorruptionRefusedByQueries(t *testing.T) {
417		f := newFixture(t)
418	
419		const badRecord = `{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}`
420		submitBatch(t, f.dir, "["+badRecord+"]")
421	
422		cases := []struct {
