48	// immediately after the closing brace; anything required past it (for example
49	// "nothing may follow the envelope") stays the caller's check on the same
50	// decoder.
51	func readStrictJSONObject(dec *json.Decoder, wording strictObjectWording, visit func(key string, val json.RawMessage) error) (map[string]json.RawMessage, error) {
52		tok, err := dec.Token()
53		if err != nil {
